  function initialData(){return{catalog:[{id:'A',size:'窄',temp:1,rock:'中软',depth:80,flow:55,cost:35},{id:'B',size:'窄',temp:2,rock:'硬',depth:88,flow:48,cost:58},{id:'C',size:'中',temp:2,rock:'中软',depth:62,flow:90,cost:52},{id:'D',size:'中',temp:3,rock:'硬',depth:83,flow:66,cost:78},{id:'E',size:'宽',temp:3,rock:'中软',depth:55,flow:96,cost:80},{id:'F',size:'窄',temp:3,rock:'硬',depth:74,flow:63,cost:69}]};}
